mapper.select:
select t.template_id as "templateId", t.business_type as "businessType", t.template_version as "templateVersion", t.effective_date as "effectiveDate", t.system_use_yn as "systemUseYn", t.status as "status", f.file_token as "fileToken", f.original_file_name as "originalFileName" from excel_upload_templates t left join excel_upload_template_files f on f.template_id = t.template_id
t.status != 'DELETED'
and t.business_type = #{businessType}
and t.effective_date <= CAST(#{effectiveDate} AS date)
order by t.effective_date desc, t.template_version desc limit #{limit} offset #{offset}

select h.upload_id as "uploadId", f.original_file_name as "originalFileName", f.uploader_user_id as "uploaderUserId", h.total_count as "totalCount", h.success_count as "successCount", h.error_count as "errorCount", h.excluded_count as "excludedCount", h.saved_count as "savedCount", h.processing_time_millis as "processingTimeMillis", h.processed_at as "processedAt" from excel_upload_histories h join excel_upload_files f on f.upload_id = h.upload_id
h.status != 'DELETED'
and h.upload_id = #{uploadId}
and f.original_file_name ilike concat('%', #{originalFileName}, '%')
order by h.processed_at desc limit #{limit} offset #{offset}
